// The precision benchmark from Section 7's acceptance criteria. Corpus
// content lives under tests/corpus/{malicious,clean}/ — generated by
// scripts/generate-corpus.mjs, checked in as a real dataset, and NOT
// regenerated automatically here (see that script's header comment for
// why). This test only reads what's already on disk and measures the
// engine's behavior against it.

import { describe, it, expect } from 'vitest'
import { readdirSync, mkdtempSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { buildInventory, ADAPTERS } from '../../src/discovery/index.js'
import type { DiscoveryRoots } from '../../src/discovery/types.js'
import { runChecks } from '../../src/rules/engine.js'

const CORPUS_ROOT = dirname(fileURLToPath(import.meta.url))
const MALICIOUS_DIR = join(CORPUS_ROOT, 'malicious')
const CLEAN_DIR = join(CORPUS_ROOT, 'clean')

const MIN_MALICIOUS = 50
const MIN_CLEAN = 100
const PRECISION_TARGET = 0.9

function sampleIds(dir: string): string[] {
  return readdirSync(dir, { withFileTypes: true })
    .filter((e) => e.isDirectory())
    .map((e) => e.name)
}

/**
 * homeDir is a fresh, empty temp directory, deliberately never this
 * machine's real home — pointing discovery at the real ~/.claude.json or
 * ~/.claude/skills here would mix this developer's actual environment into
 * a benchmark that's supposed to measure the rules against known samples
 * only.
 */
function scanSample(sampleDir: string, isolatedHome: string) {
  const roots: DiscoveryRoots = { projectDir: sampleDir, homeDir: isolatedHome, platform: 'linux', env: {} }
  return runChecks(buildInventory(roots, ADAPTERS))
}

describe('benchmark corpus', () => {
  it(`has at least ${MIN_MALICIOUS} malicious samples and ${MIN_CLEAN} clean samples`, () => {
    expect(sampleIds(MALICIOUS_DIR).length).toBeGreaterThanOrEqual(MIN_MALICIOUS)
    expect(sampleIds(CLEAN_DIR).length).toBeGreaterThanOrEqual(MIN_CLEAN)
  })

  it(`meets the ${PRECISION_TARGET * 100}% precision target`, () => {
    const isolatedHome = mkdtempSync(join(tmpdir(), 'blisspoint-security-bench-home-'))
    try {
      const maliciousIds = sampleIds(MALICIOUS_DIR)
      const cleanIds = sampleIds(CLEAN_DIR)

      let truePositives = 0
      const falseNegatives: string[] = []
      for (const id of maliciousIds) {
        const result = scanSample(join(MALICIOUS_DIR, id), isolatedHome)
        if (result.findings.length > 0) truePositives++
        else falseNegatives.push(id)
      }

      let falsePositives = 0
      const falsePositiveDetail: string[] = []
      for (const id of cleanIds) {
        const result = scanSample(join(CLEAN_DIR, id), isolatedHome)
        if (result.findings.length > 0) {
          falsePositives++
          falsePositiveDetail.push(`${id}: ${result.findings.map((f) => f.ruleId).join(', ')}`)
        }
      }

      const precision = truePositives / (truePositives + falsePositives)
      const recall = truePositives / maliciousIds.length

      // Deliberately printed even on success — this is the number the
      // README cites, and it should be visible in CI output without
      // needing to force a failure to see it.
      // eslint-disable-next-line no-console
      console.log(
        [
          '',
          'Benchmark corpus results:',
          `  Malicious: ${maliciousIds.length} samples, ${truePositives} caught, ${falseNegatives.length} missed`,
          `  Clean:     ${cleanIds.length} samples, ${falsePositives} false positive(s)`,
          `  Precision: ${(precision * 100).toFixed(1)}%`,
          `  Recall:    ${(recall * 100).toFixed(1)}%`,
          falseNegatives.length ? `  Missed: ${falseNegatives.join(', ')}` : '',
          falsePositiveDetail.length ? `  False positives:\n    ${falsePositiveDetail.join('\n    ')}` : '',
        ]
          .filter(Boolean)
          .join('\n')
      )

      expect(precision).toBeGreaterThanOrEqual(PRECISION_TARGET)
    } finally {
      rmSync(isolatedHome, { recursive: true, force: true })
    }
  })

  it('catches at least one sample for every rule ID in the malicious corpus (coverage, not just aggregate precision)', () => {
    const isolatedHome = mkdtempSync(join(tmpdir(), 'blisspoint-security-bench-home-'))
    try {
      const ruleIdsSeen = new Set<string>()
      for (const id of sampleIds(MALICIOUS_DIR)) {
        const result = scanSample(join(MALICIOUS_DIR, id), isolatedHome)
        for (const finding of result.findings) ruleIdsSeen.add(finding.ruleId)
      }
      const expectedRuleIds = [
        'MCP-CFG-001',
        'MCP-CFG-002',
        'MCP-CFG-003',
        'MCP-CFG-004',
        'SRC-001',
        'SRC-002',
        'SRC-003',
        'SRC-004',
        'SRC-005',
        'TXT-001',
        'TXT-002',
        'TXT-003',
        'TXT-004',
        'TXT-005',
      ]
      const missing = expectedRuleIds.filter((id) => !ruleIdsSeen.has(id))
      expect(missing).toEqual([])
    } finally {
      rmSync(isolatedHome, { recursive: true, force: true })
    }
  })
})
